-- 218: Help Center — Technical support guides for platform administrators (restart,
-- logs, HashiCorp Vault, key rotation, upgrades, backups, troubleshooting), the
-- "Technical support" group name, and Ask Bayanis answering how-to questions.
-- Help texts follow the pattern of db/204. Safe to run more than once.

BEGIN;

CREATE TEMP TABLE _tr218 (key_code text, base_text text, ar_text text) ON COMMIT DROP;


-- Human work on the old English is kept (marked out of date below), never overwritten.
CREATE TEMP TABLE _keep218 ON COMMIT DROP AS
SELECT tr.key_id FROM bayanat.translations tr
JOIN bayanat.translation_keys tk ON tk.key_id = tr.key_id
JOIN _tr218 n ON n.key_code = tk.key_code
WHERE tr.language_code = 'ar' AND tr.status_code IN ('HUMAN_EDITED', 'VERIFIED') AND tk.base_text <> n.base_text;

UPDATE bayanat.translations tr SET status_code = 'STALE'
FROM bayanat.translation_keys tk, _tr218 n
WHERE tr.key_id = tk.key_id AND tk.key_code = n.key_code AND tk.base_text <> n.base_text AND tr.status_code <> 'MISSING';

UPDATE bayanat.translation_keys tk SET base_text = n.base_text
FROM _tr218 n WHERE tk.key_code = n.key_code AND tk.base_text <> n.base_text;

SELECT 'HELP_DOCS', key_code, base_text FROM _tr218
ON CONFLICT (key_code) DO NOTHING;

SELECT tk.key_id, 'ar', n.ar_text, 'AI_TRANSLATED', 'Anthropic Claude:claude-opus-5-5', now()
FROM _tr218 n
JOIN bayanat.translation_keys tk ON tk.key_code = n.key_code AND tk.base_text = n.base_text
WHERE tk.key_id NOT IN (SELECT key_id FROM _keep218)
ON CONFLICT (key_id, language_code) DO UPDATE
  SET translated_text = EXCLUDED.translated_text, status_code = 'AI_TRANSLATED',
      model_ref_text = EXCLUDED.model_ref_text, translated_at = now(), verified_at = NULL, verified_by_user_id = NULL
  WHERE bayanat.translations.status_code IN ('MISSING', 'STALE', 'AI_TRANSLATED')
     OR bayanat.translations.translated_text IS NULL;

-- The Help Center's "Technical support" group (lib/i18n/en.ts help.groupSupport).
SELECT tk.category_code, 'help.groupSupport', 'Technical support'
FROM bayanat.translation_keys tk WHERE tk.key_code = 'help.groupAdmin'
ON CONFLICT (key_code) DO NOTHING;

SELECT key_id, 'ar', 'الدعم الفني', 'VERIFIED', now(), now() FROM bayanat.translation_keys WHERE key_code = 'help.groupSupport'
ON CONFLICT (key_id, language_code) DO NOTHING;

COMMIT;
